/**
 * Guards for everything a change *points at*: assignees, project leads, labels,
 * parent issues and reply targets.
 *
 * A reference must be usable from the workspace the change is made in. One
 * that belongs to another workspace is a tenant violation (`assertOrgScope`
 * throws `TenantScopeError`); one that does not exist, is archived, is not a
 * current member, or is otherwise not a valid target is `NotFoundError`. All
 * of these run before a service writes or emits anything, so a refused change
 * leaves no trace.
 */
import { isArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import { NotFoundError, requireFound } from "./_support";
import type {
  CommentId,
  IssueId,
  LabelId,
  OrgId,
  ProjectId,
  TenantScoped,
  UserId,
} from "@/types/common";
import type { Comment } from "@/types/comment";
import type { Issue } from "@/types/issue";
import type { Actor, Member } from "@/types/member";

/**
 * Returns the row an org-scoped lookup found. When it found nothing, asks
 * whether the row exists in some other organization: that is a tenant
 * violation, anything else is not found.
 */
async function requireInScope<T extends TenantScoped>(
  actor: Actor,
  entity: string,
  id: string,
  inOrg: T | null,
  inAnyOrg: () => Promise<T | null>,
): Promise<T> {
  if (inOrg !== null) return inOrg;

  const elsewhere = await inAnyOrg();
  if (elsewhere !== null) assertOrgScope(actor, elsewhere.orgId);

  throw new NotFoundError(entity, id);
}

/** The person must be a current member of the workspace. */
export async function requireCurrentMember(
  orgId: OrgId,
  userId: UserId,
): Promise<Member> {
  return requireFound(
    await memberRepo.findCurrentMember(orgId, userId),
    "Member",
    userId,
  );
}

/** Every label must be one of the workspace's own. */
export async function requireOwnLabels(
  actor: Actor,
  orgId: OrgId,
  labelIds: readonly LabelId[],
): Promise<void> {
  const wanted = [...new Set(labelIds)];
  const own = new Set(
    (await labelRepo.findLabelsByIds(orgId, wanted)).map((label) => label.id),
  );
  const missing = wanted.filter((labelId) => !own.has(labelId));
  if (missing.length === 0) return;

  for (const label of await labelRepo.findLabelsByIdsInAnyOrg(missing)) {
    assertOrgScope(actor, label.orgId);
  }
  throw new NotFoundError("Label", missing.join(", "));
}

/** A parent must be a live issue of the same project as the sub-issue. */
export async function requireParentIssue(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
  parentId: IssueId,
): Promise<Issue> {
  const parent = await requireInScope(
    actor,
    "Issue",
    parentId,
    await issueRepo.findIssueById(orgId, parentId),
    () => issueRepo.findIssueInAnyOrg(parentId),
  );

  if (isArchived(parent) || parent.projectId !== projectId) {
    throw new NotFoundError("Issue", parentId);
  }
  return parent;
}

/** A reply must answer a live, top-level comment on the same issue. */
export async function requireReplyTarget(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
  parentId: CommentId,
): Promise<Comment> {
  const parent = await requireInScope(
    actor,
    "Comment",
    parentId,
    await commentRepo.findCommentById(orgId, parentId),
    () => commentRepo.findCommentInAnyOrg(parentId),
  );

  if (
    isArchived(parent) ||
    parent.issueId !== issueId ||
    parent.parentId !== null
  ) {
    throw new NotFoundError("Comment", parentId);
  }
  return parent;
}

