/**
 * Everything a change points at must be usable from the workspace the change
 * is made in: assignees, project leads, labels, parent issues, reply targets
 * and mentions. A refused change leaves no trace.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { subscribe } from "@/lib/event-bus";
import { TenantScopeError } from "@/lib/tenant";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { CreateProjectInput } from "@/schemas/project";
import type { CommentId, IssueId, LabelId, OrgId, UserId } from "@/types/common";
import type { Comment } from "@/types/comment";
import type { Issue } from "@/types/issue";
import type { EventHandler, TaskflowEventType } from "@/types/event";

let cleanup: () => void;
let acme: Tenant;
let globex: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  acme = await createTenant("refacme");
  globex = await createTenant("refglobex");
});

afterAll(() => {
  cleanup();
});

/** Records every event of the given types until the returned stop is called. */
function record(...types: TaskflowEventType[]) {
  const seen: { type: string; payload: unknown }[] = [];
  const offs = types.map((type) =>
    subscribe(type, ((payload: unknown) => {
      seen.push({ type, payload });
    }) as EventHandler<typeof type>),
  );
  return { seen, stop: () => offs.forEach((off) => off()) };
}

const emitted = record();
afterEach(() => emitted.stop());

async function refused(promise: Promise<unknown>): Promise<unknown> {
  return promise.then(
    () => {
      throw new Error("expected the change to be refused");
    },
    (error: unknown) => error,
  );
}

async function issueCount(tenant: Tenant): Promise<number> {
  return issueRepo.countIssues(tenant.org.id, tenant.project.id, { includeArchived: true });
}

async function newProject(tenant: Tenant, slug: string, key: string) {
  return projectService.createProject(tenant.actors.owner, {
    orgId: tenant.org.id,
    name: `${slug} project`,
    slug,
    key,
    description: null,
    visibility: "org",
    leadId: null,
    color: "#6366f1",
    targetDate: null,
  });
}

async function newIssue(tenant: Tenant, title: string, projectId = tenant.project.id) {
  return issueService.createIssue(tenant.actors.member, issueInput(tenant.org.id, projectId, { title }));
}

async function reply(
  tenant: Tenant,
  issue: Issue,
  parentId: CommentId | null,
  overrides: { mentionedUserIds?: UserId[]; body?: string } = {},
): Promise<Comment> {
  return commentService.createComment(tenant.actors.member, {
    orgId: tenant.org.id,
    issueId: issue.id,
    body: overrides.body ?? "a reply",
    parentId,
    mentionedUserIds: overrides.mentionedUserIds ?? [],
  });
}

describe("labels", () => {
  it("never shows a label from another workspace, even if one was attached", async () => {
    const foreign = await labelRepo.insertLabel({
      orgId: globex.org.id,
      name: "Globex secret",
      color: "#ff0000",
      description: null,
    });
    const own = await labelRepo.insertLabel({
      orgId: acme.org.id,
      name: "Acme own",
      color: "#00ff00",
      description: null,
    });
    const issue = await newIssue(acme, "Label leak");

    // A stale attachment written before the checks existed.
    await labelRepo.setIssueLabels(acme.org.id, issue.id, [foreign.id, own.id]);

    const loaded = await issueService.getIssue(acme.actors.member, acme.org.id, issue.id);
    expect(loaded.labels.map((label) => label.name)).toEqual(["Acme own"]);
    expect(loaded.issue.labelIds).toEqual([own.id]);

    const listed = await issueRepo.listIssuesWithRelations({
      orgId: acme.org.id,
      projectId: acme.project.id,
      limit: 25,
      cursor: null,
    });
    const row = listed.items.find((item) => item.issue.id === issue.id);
    expect(row?.labels.map((label) => label.name)).toEqual(["Acme own"]);

    const byForeign = await issueRepo.listIssues({
      orgId: acme.org.id,
      labelIds: [foreign.id],
      limit: 25,
      cursor: null,
    });
    expect(byForeign.items).toEqual([]);
  });

  it("refuses another workspace's label on create and changes nothing", async () => {
    const foreign = await labelRepo.insertLabel({
      orgId: globex.org.id,
      name: "Globex only",
      color: "#ff0000",
      description: null,
    });
    const before = await issueCount(acme);
    const events = record("issue.created");

    const error = await refused(
      issueService.createIssue(acme.actors.member, {
        ...issueInput(acme.org.id, acme.project.id, { title: "Foreign label" }),
        labelIds: [foreign.id],
      }),
    );
    events.stop();

    expect(error).toBeInstanceOf(TenantScopeError);
    expect(await issueCount(acme)).toBe(before);
    expect(events.seen).toEqual([]);
  });

  it("refuses an unknown label as not found and keeps the existing labels on update", async () => {
    const own = await labelRepo.insertLabel({
      orgId: acme.org.id,
      name: "Keep me",
      color: "#00ff00",
      description: null,
    });
    const issue = await newIssue(acme, "Keeps labels");
    await issueService.updateIssue(acme.actors.member, {
      orgId: acme.org.id,
      issueId: issue.id,
      labelIds: [own.id],
    });

    const error = await refused(
      issueService.updateIssue(acme.actors.member, {
        orgId: acme.org.id,
        issueId: issue.id,
        title: "Renamed",
        labelIds: ["01HZZZNOSUCHLABEL0000000000" as LabelId],
      }),
    );
    expect(error).toBeInstanceOf(NotFoundError);

    const after = await issueRepo.findIssueById(acme.org.id, issue.id);
    expect(after?.title).toBe("Keeps labels");
    expect(after?.labelIds).toEqual([own.id]);
  });

  it("refuses another workspace's label on update", async () => {
    const foreign = await labelRepo.insertLabel({
      orgId: globex.org.id,
      name: "Globex again",
      color: "#ff0000",
      description: null,
    });
    const issue = await newIssue(acme, "Update with foreign label");

    const error = await refused(
      issueService.updateIssue(acme.actors.member, {
        orgId: acme.org.id,
        issueId: issue.id,
        labelIds: [foreign.id],
      }),
    );
    expect(error).toBeInstanceOf(TenantScopeError);
    expect((await issueRepo.findIssueById(acme.org.id, issue.id))?.labelIds).toEqual([]);
  });
});

describe("parent issues", () => {
  it("accepts a live parent in the same project", async () => {
    const parent = await newIssue(acme, "Parent");
    const child = await issueService.createIssue(acme.actors.member, {
      ...issueInput(acme.org.id, acme.project.id, { title: "Child" }),
      parentId: parent.id,
    });
    expect(child.parentId).toBe(parent.id);
  });

  it("refuses a parent from another workspace as a tenant violation", async () => {
    const foreignParent = await newIssue(globex, "Globex parent");
    const before = await issueCount(acme);

    const error = await refused(
      issueService.createIssue(acme.actors.member, {
        ...issueInput(acme.org.id, acme.project.id, { title: "Orphan" }),
        parentId: foreignParent.id,
      }),
    );

    expect(error).toBeInstanceOf(TenantScopeError);
    expect(await issueCount(acme)).toBe(before);
  });

  it("refuses a parent from another project of the same workspace as not found", async () => {
    const other = await newProject(acme, "second", "SEC");
    const parent = await newIssue(acme, "Other project parent", other.id);
    const before = await issueCount(acme);

    const error = await refused(
      issueService.createIssue(acme.actors.member, {
        ...issueInput(acme.org.id, acme.project.id, { title: "Wrong project" }),
        parentId: parent.id,
      }),
    );

    expect(error).toBeInstanceOf(NotFoundError);
    expect(await issueCount(acme)).toBe(before);
  });

  it("refuses an archived or unknown parent as not found", async () => {
    const parent = await newIssue(acme, "Soon archived");
    await issueService.archiveIssue(acme.actors.admin, acme.org.id, parent.id);

    for (const parentId of [parent.id, "01HZZZNOSUCHISSUE0000000000" as IssueId]) {
      const error = await refused(
        issueService.createIssue(acme.actors.member, {
          ...issueInput(acme.org.id, acme.project.id, { title: "Bad parent" }),
          parentId,
        }),
      );
      expect(error).toBeInstanceOf(NotFoundError);
    }
  });
});

describe("assignees and project leads", () => {
  it("refuses a stranger as assignee on create and on assign", async () => {
    const before = await issueCount(acme);
    const events = record("issue.created", "issue.assigned", "issue.updated");

    const created = await refused(
      issueService.createIssue(
        acme.actors.member,
        issueInput(acme.org.id, acme.project.id, {
          title: "Stranger",
          assigneeId: globex.userIds.member,
        }),
      ),
    );
    expect(created).toBeInstanceOf(NotFoundError);
    expect(await issueCount(acme)).toBe(before);

    const issue = await newIssue(acme, "Assign me");
    events.seen.length = 0;

    const assigned = await refused(
      issueService.assignIssue(acme.actors.admin, {
        orgId: acme.org.id,
        issueId: issue.id,
        assigneeId: globex.userIds.member,
      }),
    );
    events.stop();

    expect(assigned).toBeInstanceOf(NotFoundError);
    expect(events.seen).toEqual([]);
    expect((await issueRepo.findIssueById(acme.org.id, issue.id))?.assigneeId).toBeNull();
  });

  it("refuses a member who has left as assignee, but allows un-assigning", async () => {
    const leaver = await createLeaver(acme, "assignleaver");
    const issue = await newIssue(acme, "Leaver assignment");

    const error = await refused(
      issueService.assignIssue(acme.actors.admin, {
        orgId: acme.org.id,
        issueId: issue.id,
        assigneeId: leaver,
      }),
    );
    expect(error).toBeInstanceOf(NotFoundError);

    const assigned = await issueService.assignIssue(acme.actors.admin, {
      orgId: acme.org.id,
      issueId: issue.id,
      assigneeId: acme.userIds.member,
    });
    expect(assigned.assigneeId).toBe(acme.userIds.member);

    const cleared = await issueService.assignIssue(acme.actors.admin, {
      orgId: acme.org.id,
      issueId: issue.id,
      assigneeId: null,
    });
    expect(cleared.assigneeId).toBeNull();
  });

  it("refuses a stranger or a former member as project lead", async () => {
    const leaver = await createLeaver(acme, "leadleaver");

    for (const leadId of [globex.userIds.owner, leaver]) {
      const input: CreateProjectInput = {
        orgId: acme.org.id,
        name: "Led by nobody",
        slug: "led-by-nobody",
        key: "LBN",
        description: null,
        visibility: "org",
        leadId,
        color: "#6366f1",
        targetDate: null,
      };
      const error = await refused(projectService.createProject(acme.actors.owner, input));
      expect(error).toBeInstanceOf(NotFoundError);
    }

    const project = await newProject(acme, "lead-target", "LED");
    const updated = await refused(
      projectService.updateProject(acme.actors.owner, {
        orgId: acme.org.id,
        projectId: project.id,
        leadId: globex.userIds.owner,
      }),
    );
    expect(updated).toBeInstanceOf(NotFoundError);

    const ok = await projectService.updateProject(acme.actors.owner, {
      orgId: acme.org.id,
      projectId: project.id,
      leadId: acme.userIds.admin,
    });
    expect(ok.leadId).toBe(acme.userIds.admin);
  });
});

describe("replies", () => {
  it("accepts a reply to a live top-level comment on the same issue", async () => {
    const issue = await newIssue(acme, "Thread");
    const top = await reply(acme, issue, null);
    const nested = await reply(acme, issue, top.id);
    expect(nested.parentId).toBe(top.id);
  });

  it("refuses a reply to a comment on a different issue as not found", async () => {
    const one = await newIssue(acme, "Issue one");
    const two = await newIssue(acme, "Issue two");
    const onOne = await reply(acme, one, null);

    const events = record("comment.created");
    const error = await refused(reply(acme, two, onOne.id));
    events.stop();

    expect(error).toBeInstanceOf(NotFoundError);
    expect(events.seen).toEqual([]);
    expect(await commentRepo.listThread(acme.org.id, two.id)).toEqual([]);
  });

  it("refuses a reply to a deleted comment and to a reply", async () => {
    const issue = await newIssue(acme, "Deleted anchor");
    const top = await reply(acme, issue, null);
    const nested = await reply(acme, issue, top.id);
    const doomed = await reply(acme, issue, null);
    await commentService.deleteComment(acme.actors.admin, {
      orgId: acme.org.id,
      commentId: doomed.id,
    });

    for (const parentId of [doomed.id, nested.id, "01HZZZNOSUCHCOMMENT00000000" as CommentId]) {
      const error = await refused(reply(acme, issue, parentId));
      expect(error).toBeInstanceOf(NotFoundError);
    }

    const thread = await commentRepo.listThread(acme.org.id, issue.id);
    expect(thread.flatMap((node) => [node.comment, ...node.replies])).toHaveLength(3);
  });

  it("refuses a reply to another workspace's comment as a tenant violation", async () => {
    const theirs = await newIssue(globex, "Their thread");
    const theirComment = await reply(globex, theirs, null);
    const mine = await newIssue(acme, "My thread");

    const error = await refused(reply(acme, mine, theirComment.id));
    expect(error).toBeInstanceOf(TenantScopeError);
  });
});

describe("mentions", () => {
  it("drops composer ids that are strangers or former members, keeps current ones", async () => {
    const leaver = await createLeaver(acme, "mentionleaver");
    const issue = await newIssue(acme, "Mentions");

    const events = record("comment.created");
    const comment = await reply(acme, issue, null, {
      body: "hello @admin",
      mentionedUserIds: [leaver, globex.userIds.owner, acme.userIds.owner],
    });
    events.stop();

    expect([...comment.mentionedUserIds].sort()).toEqual(
      [acme.userIds.admin, acme.userIds.owner].sort(),
    );
    expect(events.seen).toHaveLength(1);
    expect(
      [...(events.seen[0]?.payload as { mentionedUserIds: readonly UserId[] }).mentionedUserIds].sort(),
    ).toEqual([acme.userIds.admin, acme.userIds.owner].sort());
  });

  it("ignores an @handle whose owner has left the workspace", async () => {
    const leaver = await createLeaver(acme, "handleleaver");
    const issue = await newIssue(acme, "Handle mentions");

    const comment = await reply(acme, issue, null, { body: "ping @handleleaver please" });
    expect(comment.mentionedUserIds).not.toContain(leaver);
    expect(comment.mentionedUserIds).toEqual([]);
  });
});

/** Adds a member to `tenant`, then removes them again; returns their user id. */
async function createLeaver(tenant: Tenant, name: string): Promise<UserId> {
  const { insertUser } = await import("@/server/repositories/user-repository");
  const user = await insertUser({
    email: `${name}@${tenant.org.slug}.test`,
    name,
    passwordHash: "seed",
  });
  const member = await memberRepo.insertMember(tenant.org.id, user.id, "member", null);
  await memberRepo.archiveMember(tenant.org.id, member.id);
  return user.id;
}

export type { OrgId };

