    const issue = await newIssue(acme, "Assign me");
    events.seen.length = 0;

    const assigned = await refused(
      issueService.assignIssue(acme.actors.admin, {
        orgId: acme.org.id,
        issueId: issue.id,
        assigneeId: globex.userIds.member,
      }),
    );
    events.stop();

    expect(assigned).toBeInstanceOf(NotFoundError);
    expect(events.seen).toEqual([]);
    expect((await issueRepo.findIssueById(acme.org.id, issue.id))?.assigneeId).toBeNull();
  });

  it("refuses a member who has left as assignee, but allows un-assigning", async () => {
    const leaver = await createLeaver(acme, "assignleaver");
    const issue = await newIssue(acme, "Leaver assignment");

    const error = await refused(
      issueService.assignIssue(acme.actors.admin, {
        orgId: acme.org.id,
        issueId: issue.id,
        assigneeId: leaver,
      }),
    );
    expect(error).toBeInstanceOf(NotFoundError);

    const assigned = await issueService.assignIssue(acme.actors.admin, {
      orgId: acme.org.id,
      issueId: issue.id,
      assigneeId: acme.userIds.member,
    });
    expect(assigned.assigneeId).toBe(acme.userIds.member);

    const cleared = await issueService.assignIssue(acme.actors.admin, {
      orgId: acme.org.id,
      issueId: issue.id,
      assigneeId: null,
    });
    expect(cleared.assigneeId).toBeNull();
  });

  it("refuses a stranger or a former member as project lead", async () => {
    const leaver = await createLeaver(acme, "leadleaver");

    for (const leadId of [globex.userIds.owner, leaver]) {
      const input: CreateProjectInput = {
        orgId: acme.org.id,
        name: "Led by nobody",
        slug: "led-by-nobody",
        key: "LBN",
        description: null,
        visibility: "org",
        leadId,
        color: "#6366f1",
        targetDate: null,
      };
      const error = await refused(projectService.createProject(acme.actors.owner, input));
      expect(error).toBeInstanceOf(NotFoundError);
    }

    const project = await newProject(acme, "lead-target", "LED");
    const updated = await refused(
      projectService.updateProject(acme.actors.owner, {
        orgId: acme.org.id,
        projectId: project.id,
        leadId: globex.userIds.owner,
      }),
    );
    expect(updated).toBeInstanceOf(NotFoundError);

    const ok = await projectService.updateProject(acme.actors.owner, {
      orgId: acme.org.id,
      projectId: project.id,
      leadId: acme.userIds.admin,
    });
    expect(ok.leadId).toBe(acme.userIds.admin);
  });
});

describe("replies", () => {
  it("accepts a reply to a live top-level comment on the same issue", async () => {
    const issue = await newIssue(acme, "Thread");
    const top = await reply(acme, issue, null);
    const nested = await reply(acme, issue, top.id);
    expect(nested.parentId).toBe(top.id);
  });

  it("refuses a reply to a comment on a different issue as not found", async () => {
    const one = await newIssue(acme, "Issue one");
    const two = await newIssue(acme, "Issue two");
    const onOne = await reply(acme, one, null);

    const events = record("comment.created");
    const error = await refused(reply(acme, two, onOne.id));
    events.stop();

    expect(error).toBeInstanceOf(NotFoundError);
    expect(events.seen).toEqual([]);
    expect(await commentRepo.listThread(acme.org.id, two.id)).toEqual([]);
  });

  it("refuses a reply to a deleted comment and to a reply", async () => {
    const issue = await newIssue(acme, "Deleted anchor");
    const top = await reply(acme, issue, null);
    const nested = await reply(acme, issue, top.id);
    const doomed = await reply(acme, issue, null);
    await commentService.deleteComment(acme.actors.admin, {
      orgId: acme.org.id,
      commentId: doomed.id,
    });

    for (const parentId of [doomed.id, nested.id, "01HZZZNOSUCHCOMMENT00000000" as CommentId]) {
      const error = await refused(reply(acme, issue, parentId));
      expect(error).toBeInstanceOf(NotFoundError);
    }

    const thread = await commentRepo.listThread(acme.org.id, issue.id);
    expect(thread.flatMap((node) => [node.comment, ...node.replies])).toHaveLength(3);
  });

  it("refuses a reply to another workspace's comment as a tenant violation", async () => {
    const theirs = await newIssue(globex, "Their thread");
    const theirComment = await reply(globex, theirs, null);
    const mine = await newIssue(acme, "My thread");

    const error = await refused(reply(acme, mine, theirComment.id));
    expect(error).toBeInstanceOf(TenantScopeError);
  });
});

describe("mentions", () => {
  it("drops composer ids that are strangers or former members, keeps current ones", async () => {
    const leaver = await createLeaver(acme, "mentionleaver");
    const issue = await newIssue(acme, "Mentions");

    const events = record("comment.created");
    const comment = await reply(acme, issue, null, {
      body: "hello @admin",
      mentionedUserIds: [leaver, globex.userIds.owner, acme.userIds.owner],
    });
    events.stop();

    expect([...comment.mentionedUserIds].sort()).toEqual(
      [acme.userIds.admin, acme.userIds.owner].sort(),
    );
    expect(events.seen).toHaveLength(1);
    expect(
      [...(events.seen[0]?.payload as { mentionedUserIds: readonly UserId[] }).mentionedUserIds].sort(),
    ).toEqual([acme.userIds.admin, acme.userIds.owner].sort());
  });

  it("ignores an @handle whose owner has left the workspace", async () => {
    const leaver = await createLeaver(acme, "handleleaver");
    const issue = await newIssue(acme, "Handle mentions");

    const comment = await reply(acme, issue, null, { body: "ping @handleleaver please" });
    expect(comment.mentionedUserIds).not.toContain(leaver);
    expect(comment.mentionedUserIds).toEqual([]);
  });
});

/** Adds a member to `tenant`, then removes them again; returns their user id. */
async function createLeaver(tenant: Tenant, name: string): Promise<UserId> {
  const { insertUser } = await import("@/server/repositories/user-repository");
  const user = await insertUser({
    email: `${name}@${tenant.org.slug}.test`,
    name,
    passwordHash: "seed",
  });
  const member = await memberRepo.insertMember(tenant.org.id, user.id, "member", null);
  await memberRepo.archiveMember(tenant.org.id, member.id);
  return user.id;
}

